INSERT INTO courses (id, admin_id, medium_id, genre_id, course_type_id, skill_id, category_id, title, slug, sub_title, introduction, introduction_details, summary, summary_details, schedule, schedule_details, schedule_pdf, age_group, duration, sessions, mini_projects, course_modules, time_required, includes, course_includes, course_highlights, course_for, course_not_for, course_problems_solved, course_learn, course_outcome, course_deliverables, course_prerequisites, course_based, intro_video_url, seat_limit, is_free_course, status, course_start_date, created_at, updated_at) VALUES (1, 1, 1, '1', 1, 1, 2, 'Watercolour Landscapes for Beginners', 'watercolour-landscapes-for-beginners', 'Learn washes, layering and colour mixing to paint glowing landscapes.', 'A step-by-step introduction to painting landscapes in watercolour.', '<p>A step-by-step introduction to painting landscapes in watercolour.</p><p>Each session is live with the instructor, followed by practice at home and feedback on what you submit in My studio.</p>', '3 parts, 8 live sessions.', '<ul><li>Flat, graded and wet-in-wet washes</li><li>Mixing clean greens and skies</li><li>Painting trees, water and light</li><li>Planning a finished landscape</li></ul>', 'Live sessions twice a week.', '<p>Part 1: Materials and first washes<br>Part 2: Skies, trees and water<br>Part 3: Your finished landscape</p>', 'schedule.pdf', 'Adult - 16 yrs and above', '4', '8', '3', '3', '2', 'Live sessions, recordings for 30 days, feedback on your work, certificate.', '{"certificate": "yes", "study_material_access": "yes"}', '["Live classes", "Feedback on every submission", "Certificate on completion"]', '["Beginners", "Adult - 16 yrs and above"]', '["Anyone looking for a recorded-only course"]', '["Not knowing where to start", "Practising without feedback"]', '["Flat, graded and wet-in-wet washes", "Mixing clean greens and skies", "Painting trees, water and light", "Planning a finished landscape"]', 'A finished piece: final landscape.', '["Certificate", "Lesson notes (PDF)", "Session recordings"]', 'None.', 'instructor_based', '/storage/uploads/courses/1/videos/trailer.mp4', NULL, 0, 1, DATE_ADD(CURDATE(), INTERVAL 21 DAY), NOW(), NOW());
