INSERT INTO courses (id, admin_id, medium_id, genre_id, course_type_id, skill_id, category_id, title, slug, sub_title, introduction, introduction_details, summary, summary_details, schedule, schedule_details, schedule_pdf, age_group, duration, sessions, mini_projects, course_modules, time_required, includes, course_includes, course_highlights, course_for, course_not_for, course_problems_solved, course_learn, course_outcome, course_deliverables, course_prerequisites, course_based, intro_video_url, seat_limit, is_free_course, status, course_start_date, created_at, updated_at) VALUES (2, 1, 3, '3', 1, 1, 2, 'Pencil Sketching Essentials', 'pencil-sketching-essentials', 'Build confident drawing skills with graphite pencils.', 'Drawing fundamentals for everyone: lines, shapes, shading and perspective.', '<p>Drawing fundamentals for everyone: lines, shapes, shading and perspective.</p><p>Each session is live with the instructor, followed by practice at home and feedback on what you submit in My studio.</p>', '3 parts, 6 live sessions.', '<ul><li>Holding the pencil and drawing confident lines</li><li>Seeing shapes and proportions</li><li>Shading with a value scale</li><li>One- and two-point perspective</li></ul>', 'Live sessions twice a week.', '<p>Part 1: Lines and shapes<br>Part 2: Light and shade<br>Part 3: Perspective and still life</p>', 'schedule.pdf', 'Junior - 12 to 15 yrs', '4', '6', '4', '3', '2', 'Live sessions, recordings for 30 days, feedback on your work, certificate.', '{"certificate": "yes", "study_material_access": "yes"}', '["Live classes", "Feedback on every submission", "Certificate on completion"]', '["Beginners", "Junior - 12 to 15 yrs"]', '["Anyone looking for a recorded-only course"]', '["Not knowing where to start", "Practising without feedback"]', '["Holding the pencil and drawing confident lines", "Seeing shapes and proportions", "Shading with a value scale", "One- and two-point perspective"]', 'A finished piece: still life sketch.', '["Certificate", "Lesson notes (PDF)", "Session recordings"]', 'None.', 'instructor_based', '/storage/uploads/courses/2/videos/trailer.mp4', NULL, 0, 1, DATE_ADD(CURDATE(), INTERVAL 28 DAY), NOW(), NOW());
