INSERT INTO courses (id, admin_id, medium_id, genre_id, course_type_id, skill_id, category_id, title, slug, sub_title, introduction, introduction_details, summary, summary_details, schedule, schedule_details, schedule_pdf, age_group, duration, sessions, mini_projects, course_modules, time_required, includes, course_includes, course_highlights, course_for, course_not_for, course_problems_solved, course_learn, course_outcome, course_deliverables, course_prerequisites, course_based, intro_video_url, seat_limit, is_free_course, status, course_start_date, created_at, updated_at) VALUES (3, 1, 5, '2', 1, 2, 2, 'Charcoal Portrait Drawing', 'charcoal-portrait-drawing', 'Draw expressive portraits with proportion, value and texture.', 'A guided course in drawing faces with charcoal, from proportions to a finished portrait.', '<p>A guided course in drawing faces with charcoal, from proportions to a finished portrait.</p><p>Each session is live with the instructor, followed by practice at home and feedback on what you submit in My studio.</p>', '3 parts, 12 live sessions.', '<ul><li>Facial proportions and placement</li><li>Drawing eyes, nose and lips</li><li>Mapping values and soft edges</li><li>Hair, skin and texture with charcoal</li></ul>', 'Live sessions twice a week.', '<p>Part 1: Proportions of the face<br>Part 2: Features in detail<br>Part 3: The finished portrait</p>', 'schedule.pdf', 'Adult - 16 yrs and above', '6', '12', '4', '3', '2', 'Live sessions, recordings for 30 days, feedback on your work, certificate.', '{"certificate": "yes", "study_material_access": "yes"}', '["Live classes", "Feedback on every submission", "Certificate on completion"]', '["Learners who know the basics", "Adult - 16 yrs and above"]', '["Anyone looking for a recorded-only course"]', '["Not knowing where to start", "Practising without feedback"]', '["Facial proportions and placement", "Drawing eyes, nose and lips", "Mapping values and soft edges", "Hair, skin and texture with charcoal"]', 'A finished piece: portrait study.', '["Certificate", "Lesson notes (PDF)", "Session recordings"]', 'Basic drawing practice.', 'instructor_based', '/storage/uploads/courses/3/videos/trailer.mp4', NULL, 0, 1, DATE_ADD(CURDATE(), INTERVAL 35 DAY), NOW(), NOW());
