INSERT INTO courses (id, admin_id, medium_id, genre_id, course_type_id, skill_id, category_id, title, slug, sub_title, introduction, introduction_details, summary, summary_details, schedule, schedule_details, schedule_pdf, age_group, duration, sessions, mini_projects, course_modules, time_required, includes, course_includes, course_highlights, course_for, course_not_for, course_problems_solved, course_learn, course_outcome, course_deliverables, course_prerequisites, course_based, intro_video_url, seat_limit, is_free_course, status, course_start_date, created_at, updated_at) VALUES (4, 1, 2, '4,1', 1, 2, 3, 'Acrylic Colour and Texture', 'acrylic-colour-and-texture', 'Explore bold colour, blending and texture with acrylics.', 'Work with fast-drying acrylics: colour harmony, blending, glazing and textured surfaces.', '<p>Work with fast-drying acrylics: colour harmony, blending, glazing and textured surfaces.</p><p>Each session is live with the instructor, followed by practice at home and feedback on what you submit in My studio.</p>', '3 parts, 10 live sessions.', '<ul><li>Colour harmony and mixing</li><li>Blending before the paint dries</li><li>Glazes and layers</li><li>Texture with palette knives and mediums</li></ul>', 'Live sessions twice a week.', '<p>Part 1: Colour and mixing<br>Part 2: Blending and layering<br>Part 3: Texture and composition</p>', 'schedule.pdf', 'Adult - 16 yrs and above', '6', '10', '3', '3', '2', 'Live sessions, recordings for 30 days, feedback on your work, certificate.', '{"certificate": "yes", "study_material_access": "yes"}', '["Live classes", "Feedback on every submission", "Certificate on completion"]', '["Learners who know the basics", "Adult - 16 yrs and above"]', '["Anyone looking for a recorded-only course"]', '["Not knowing where to start", "Practising without feedback"]', '["Colour harmony and mixing", "Blending before the paint dries", "Glazes and layers", "Texture with palette knives and mediums"]', 'A finished piece: abstract in three colours.', '["Certificate", "Lesson notes (PDF)", "Session recordings"]', 'Basic drawing practice.', 'instructor_based', '/storage/uploads/courses/4/videos/trailer.mp4', NULL, 0, 1, DATE_ADD(CURDATE(), INTERVAL 42 DAY), NOW(), NOW());
